/* Dark animated halftone backdrop, shared by chooser and login states. */
._3NH9aXAeVjt_j6_vKppevN {
    background: #141414 !important;
    isolation: isolate;
    overflow: hidden;
}
._3NH9aXAeVjt_j6_vKppevN::before {
    content: "";
    position: absolute;
    inset: -8%;
    z-index: 0;
    pointer-events: none;
    background-image: url("data:image/png;base64,");
    background-size: cover;
    background-position: center;
    opacity: .16;
    animation: sd-login-halftone-drift 42s ease-in-out infinite alternate;
    will-change: transform;
}
._3NH9aXAeVjt_j6_vKppevN::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background: radial-gradient(ellipse at center, rgba(0,0,0,.32), rgba(0,0,0,.12));
}
._3NH9aXAeVjt_j6_vKppevN .VZ6x_grhNkIYJG__jEEyp {
    position: relative;
    z-index: 2;
    background: transparent !important;
}
