@keyframes sd-login-halftone-drift {
    from { transform: translate3d(-2%, -1%, 0) scale(1.02); }
    to { transform: translate3d(2%, 1%, 0) scale(1.07); }
}
@media (prefers-reduced-motion: reduce) {
    ._3NH9aXAeVjt_j6_vKppevN::before { animation: none; }
}

/* User-supplied animated loading indicator. Preserve its original aspect ratio. */
._3NH9aXAeVjt_j6_vKppevN ._1ijPzYVvhP7myKHrnJA9Z0 img[data-sd-loading-gif="true"] {
    width: 110px !important;
    height: 73px !important;
    object-fit: contain;
    margin: 0 auto 8px !important;
    animation: none !important;
    filter: none !important;
}

/* Invert the original dark-on-white GIF and screen out its now-black backdrop.
   This preserves every animation frame while revealing the halftone underneath. */
._3NH9aXAeVjt_j6_vKppevN ._1ijPzYVvhP7myKHrnJA9Z0 {
    filter: none !important;
}
._3NH9aXAeVjt_j6_vKppevN ._1ijPzYVvhP7myKHrnJA9Z0 img[data-sd-loading-gif="true"] {
    filter: grayscale(1) invert(1) !important;
    mix-blend-mode: screen;
    background: transparent !important;
}

/* True per-frame transparency: background luminance becomes inverse alpha. */
._3NH9aXAeVjt_j6_vKppevN ._1ijPzYVvhP7myKHrnJA9Z0 img[data-sd-loading-gif="true"] {
    filter: url("#sd-spinner-transparency") !important;
    mix-blend-mode: normal !important;
    background: transparent !important;
}
